check_code:
def c(w): return sum(27-(ord(x)-64) for x in w)*len(w)
assert c('HIT')==132 and c('SBYZ')==144
r=c('YRF')
o={'A':108,'B':124,'C':112,'D':96}
assert r==o['D']
for k in 'ABC': assert r!=o[k]

o={'A':'HGF','B':'VUT','C':'KJI','D':'AAY'}
f=lambda w:all(ord(w[i])-ord(w[i+1])==1 for i in range(2))
assert [k for k,v in o.items() if not f(v)]==['D']

o={'A':'YWT','B':'XVS','C':'WUQ','D':'ZXU'}
f=lambda w:(ord(w[0])-ord(w[1]),ord(w[1])-ord(w[2]))
assert [k for k,v in o.items() if f(v)!=(2,3)]==['C']

a={'play','in','the','sunshine'};b={'the','sunshine','is','bright'}
ca={'sh','ko','zm','fq'};cb={'ko','sh','gp','rs'}
assert a&b=={'the','sunshine'} and ca&cb=={'sh','ko'}
o={'A':{'gp','sh'},'B':{'sh','ko'},'C':{'ko'},'D':{'zm'}}
assert [k for k,v in o.items() if v==ca&cb]==['B']
